
'use strict';
const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}, duration=n=>`${Math.floor(n/60)}시간 ${n%60}분`, uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(36).slice(2)}`,normalize=s=>s.normalize('NFKC').trim().replace(/\s+/g,' ');
function initialData(){const y=new Date().getFullYear(),m=new Date().getMonth(),date=(month,day)=>{const d=new Date(y,month,day,12);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};return {members:[],records:[],periods:[{id:uid(),start:date(m,24),end:date(m+1,1)},{id:uid(),start:date(m+1,2),end:date(m+1,9)},{id:uid(),start:date(m+1,10),end:date(m+1,17)}]}}
