let draftImages=[];
let data=initialData(),currentId=null,view='home',periodId=data.periods[0].id,editingId=null,kind='study',draftImage=null,photoBusy=false,pendingDelete=null,storageReady=false,photoGeneration=0;
const me=()=>data.members.find(m=>m.id===currentId),period=()=>yearPeriods().find(p=>p.id===periodId)||yearPeriods()[0],inside=(date,p=period())=>inSchoolYear(date)&&date>=p.start&&date<=p.end;
function summary(memberId){const rows=(data.studyTotals||data.records).filter(r=>r.kind==='study'&&inside(r.date)&&(!memberId||r.memberId===memberId));const total=rows.reduce((sum,r)=>sum+r.minutes,0),days=new Set(rows.map(r=>r.date)).size;return {total,days,average:days?Math.round(total/days):0}}
