$('takePhoto').onclick=()=>$('camera').click();$('choosePhoto').onclick=()=>$('photo').click();$('removePhoto').onclick=()=>{photoGeneration++;photoBusy=false;draftImage=null;draftImages=[];$('camera').value='';$('photo').value='';updatePhoto()};
async function convertPhoto(file){if(!file.type.startsWith('image/'))throw Error('사진 파일을 선택해주세요.');if(file.size>12*1024*1024)throw Error('사진은 12MB 이하로 선택해주세요.');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('이 사진 형식을 읽을 수 없어요. JPG, PNG 또는 스크린샷으로 다시 선택해주세요.'));image.src=url});const scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(img.naturalWidth*scale);canvas.height=Math.round(img.naturalHeight*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82)}finally{URL.revokeObjectURL(url)}}
async function selectPhoto(e){const files=[...e.target.files];if(!files.length)return;const generation=++photoGeneration;photoBusy=true;$('recordError').textContent='사진을 준비하고 있어요';try{const images=[];for(const file of files)images.push(await convertPhoto(file));if(generation!==photoGeneration)return;draftImages.push(...images);draftImage=draftImages[0];$('recordError').textContent='';updatePhoto()}catch(err){if(generation===photoGeneration)$('recordError').textContent=err.message}finally{if(generation===photoGeneration)photoBusy=false;e.target.value=''}}$('camera').onchange=selectPhoto;$('photo').onchange=selectPhoto;
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action)openRecord(action.dataset.action);const close=e.target.closest('[data-close]');if(close)$(close.dataset.close).close();const nav=e.target.closest('[data-view]');if(nav)setView(nav.dataset.view);const edit=e.target.closest('[data-edit]');if(edit){const r=data.records.find(r=>r.id===edit.dataset.edit&&r.memberId===currentId);if(r)openRecord(r.kind,r)}const photo=e.target.closest('[data-image]');if(photo){const r=data.records.find(r=>r.id===photo.dataset.image);if(r&&canView(r)){$('fullImage').src=recordImages(r)[Number(photo.dataset.photoIndex)||0];$('imageDialog').showModal()}}const del=e.target.closest('[data-delete]');if(del){pendingDelete=del.dataset.delete;$('deleteError').textContent='';$('deleteDialog').showModal()}});
