$('periodSelect').onchange=e=>{periodId=e.target.value;render()};$('addPeriod').onclick=()=>{if(!isTeacher())return;$('periodForm').reset();$('periodError').textContent='';$('periodDialog').showModal()};$('periodForm').onsubmit=async e=>{e.preventDefault();const start=$('startDate').value,end=$('endDate').value;if(start>end){$('periodError').textContent='종료일은 시작일 이후로 선택해주세요.';return}if(data.periods.some(p=>!p.auto&&start<=p.end&&end>=p.start)){$('periodError').textContent='기존 기간과 겹치지 않게 설정해주세요.';return}e.submitter.disabled=true;try{const next=structuredClone(data),p={id:uid(),start,end};next.periods=next.periods.filter(p=>!(p.auto&&p.start>=start&&p.end<=end));next.periods.push(p);next.periods.sort((a,b)=>a.start.localeCompare(b.start));await commit(next);periodId=p.id;render();$('periodDialog').close();notify('누적 기간을 추가했어요.')}catch(err){$('periodError').textContent=storageError(err)}finally{e.submitter.disabled=false}};
let authMode='login',pendingLoginId=null,resetMemberId=null;
