// Daily workflow model: plan (morning), plan-night, target (morning), study (night), monthly.
const workflows={plan:{title:'아침   일일 플래너 사진',family:'planner',photo:true},'plan-night':{title:'밤   일일 달성 체크 사진',family:'planner',photo:true},target:{title:'아침   순공시간 목표',family:'time',time:true},study:{title:'밤   실제 순공시간 인증',family:'time',time:true,photo:true},monthly:{title:'아침   월간 플래너 사진',family:'planner',photo:true},'monthly-night':{title:'밤   월간 달성 체크 사진',family:'planner',photo:true}};
const participationNames={both:'플래너 + 시간체크',planner:'플래너만',time:'시간체크만'};
let participationMemberId=null,threadId=null,plannerMode='weekly';
function canView(r){return !!me()&&(r.memberId===currentId||isTeacher()||r.visibility!=='private')}
function allowed(k,member=me()){return !!member&&member.role!=='teacher'&&!!workflows[k]&&(workflows[k].family==='all'||(member.participation||'both')==='both'||workflows[k].family===member.participation)}
function lookup(memberId,k,date){return data.records.find(r=>r.memberId===memberId&&r.kind===k&&r.date===date)}
function applyKind(){const w=workflows[kind];$('recordTitle').textContent=w.title;$('timeFields').hidden=!w.time;$('hours').required=!!w.time;$('minutes').required=!!w.time;$('hours').disabled=!w.time;$('minutes').disabled=!w.time;$('photoBox').hidden=!w.photo;$('photoLabel').hidden=!w.photo;$('visibilityField').hidden=false;$('recordMonth').hidden=kind!=='monthly';$('monthLabel').hidden=kind!=='monthly';$('recordMonth').required=kind==='monthly';$('recordDate').hidden=kind==='monthly';$('dateLabel').hidden=kind==='monthly';$('recordDate').required=kind!=='monthly';$('recordDate').disabled=!!editingId||kind==='monthly';$('recordMonth').disabled=!!editingId;$('workflowKind').disabled=true;$('workflowKind').hidden=true;document.querySelector('label[for=workflowKind]').hidden=true;document.querySelector('label[for=minutes]').textContent='분';$('timeFields').classList.toggle('target-time',kind==='target');$('photoHelp').textContent=kind==='plan'?'아침에 일일 플래너의 오늘 할 일을 찍어 올려주세요.':kind==='plan-night'?'밤에 일일 플래너의 오늘 달성 여부를 체크한 뒤 새 사진을 올려주세요.':kind==='monthly'?'아침에 이번 달 목표와 계획을 작성한 월간 플래너 사진을 올려주세요.':kind==='monthly-night'?'밤에 월간 플래너의 달성 여부를 체크한 뒤 사진을 올려주세요.':'열품타 캡처 등 실제 순공시간을 확인할 수 있는 사진을 올려주세요.';$('duplicateHint').textContent=kind==='target'?'사진 없이 오늘 목표만 입력해요. 목표는 누적 순공시간에 더하지 않습니다.':kind==='monthly'?'월별 계획 사진을 저장합니다. 밤 달성 체크 사진은 날짜별로 따로 남겨요.':'같은 날짜 같은 단계는 수정 저장되어 중복 집계되지 않아요.';const timeLabel=document.querySelector('label[for="hours"]');if(timeLabel)timeLabel.textContent=kind==='target'?'오늘 목표 시간':'실제 순공시간';updateTimePreview()}
function formDate(){return kind==='monthly'?$('recordMonth').value+'-01':$('recordDate').value}
function loadDateDraft(){if(editingId)return;photoGeneration++;photoBusy=false;$('recordError').textContent='';const existing=lookup(currentId,kind,formDate());draftImages=recordImages(existing);draftImage=draftImages[0]||null;$('hours').value=existing?Math.floor(existing.minutes/60):0;$('minutes').value=existing?existing.minutes%60:0;$('recordMemo').value=existing?.memo||'';$('visibility').value=existing?.visibility||'group';$('uploadName').textContent=existing?.image?'기존 인증 사진':'';$('saveRecord').textContent=existing?'기존 기록 수정하기':'기록 등록하기';updatePhoto()}
function openRecord(k='study',record=null){if(isTeacher()){notify('교사는 학생 기록에 댓글로 피드백을 남길 수 있어요.');return}if(!me()){showWelcome();return}if(!record&&!allowed(k))k=allowed('plan')?'plan':'target';if(record&&record.memberId!==currentId)return;photoGeneration++;photoBusy=false;editingId=record?.id||null;kind=record?.kind||k;$('recordForm').reset();$('workflowKind').innerHTML=Object.entries(workflows).filter(([key])=>allowed(key)||key===kind).map(([key,w])=>`<option value="${key}">${w.title}</option>`).join('');$('workflowKind').value=kind;$('recordDate').max=today();$('recordDate').value=record?.date||schoolDate();$('recordMonth').value=record?.date.slice(0,7)||$('monthFilter').value||schoolDate().slice(0,7);$('authorLabel').textContent=`${me().name}님의 기록`;$('recordError').textContent='';draftImages=recordImages(record);draftImage=draftImages[0]||null;$('hours').value=record?Math.floor(record.minutes/60):0;$('minutes').value=record?record.minutes%60:0;$('recordMemo').value=record?.memo||'';$('visibility').value=record?.visibility||'group';$('uploadName').textContent=record?.image?'기존 인증 사진':'';$('saveRecord').textContent=record?'수정 저장하기':'기록 등록하기';applyKind();if(!record)loadDateDraft();else updatePhoto();$('recordDialog').showModal()}
$('workflowKind').onchange=()=>{kind=$('workflowKind').value;applyKind();loadDateDraft()};$('recordDate').onchange=loadDateDraft;$('recordMonth').onchange=loadDateDraft;
$('recordForm').onsubmit=async e=>{e.preventDefault();$('recordError').textContent='';const w=workflows[kind];if(!me()||isTeacher())return;if(!editingId&&!allowed(kind)){$('recordError').textContent='참여 방식 설정을 확인해주세요.';return}if(photoBusy){$('recordError').textContent='사진 준비가 끝난 뒤 등록해주세요.';return}const date=formDate();if(!inSchoolYear(date)){$('recordError').textContent='설정한 학년도에 해당하는 날짜를 선택해주세요.';return}const h=Number($('hours').value),m=Number($('minutes').value),minutes=w.time?h*60+m:0;if(w.photo&&!draftImage){$('recordError').textContent='이 단계는 사진이 필요해요.';return}if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||(kind!=='monthly'&&date>today())){$('recordError').textContent='날짜를 확인해주세요. 일일 기록은 오늘 또는 이전 날짜로 등록해요.';return}if(w.time&&(!Number.isInteger(h)||!Number.isInteger(m)||h<0||m<0||m>59||minutes>1440||minutes<(kind==='target'?1:0))){$('recordError').textContent=kind==='target'?'목표는 1분~24시간으로 입력해주세요.':'실제 시간은 0분~24시간으로 입력해주세요.';return}const button=$('saveRecord');button.disabled=true;try{const next=structuredClone(data),existing=editingId?next.records.find(r=>r.id===editingId):next.records.find(r=>r.memberId===currentId&&r.kind===kind&&r.date===date);if(existing&&existing.memberId!==currentId)throw Error('내 기록만 수정할 수 있어요.');const record={id:existing?.id||uid(),memberId:currentId,kind,date,minutes,image:w.photo?draftImage:null,images:w.photo?[...draftImages]:[],memo:$('recordMemo').value.trim(),visibility:$('visibility').value,updatedAt:new Date().toISOString(),comments:existing?.comments||[],reactions:existing?.reactions||{}};if(existing)Object.assign(existing,record);else next.records.push(record);if(kind!=='monthly'&&!next.periods.some(p=>inside(date,p))){next.periods.push({id:uid(),start:date,end:date,auto:true});next.periods.sort((a,b)=>a.start.localeCompare(b.start))}await commit(next);if(kind!=='monthly'||$('weekFilter').value.slice(0,7)!==date.slice(0,7))$('weekFilter').value=date;if(kind==='monthly'){$('monthFilter').value=date.slice(0,7);view='plan';plannerMode='monthly'}else if(w.family==='planner'){view='plan';plannerMode=kind==='monthly-night'?'monthly':'weekly';$('weekFilter').value=date;$('monthFilter').value=date.slice(0,7)}else{choosePeriod(date);view='mine'}render();$('recordDialog').close();notify('기록을 저장했어요.')}catch(err){$('recordError').textContent=storageError(err)}finally{button.disabled=false}};
function groupedRecords(rows){const groups=new Map();for(const r of rows.filter(canView)){const date=r.kind==='monthly'&&view==='plan'?$('weekFilter').value:r.date,key=r.memberId+'|'+date;if(!groups.has(key))groups.set(key,{memberId:r.memberId,date,records:[]});groups.get(key).records.push(r)}return [...groups.values()].sort((a,b)=>b.date.localeCompare(a.date))}
function recordSection(r){const w=workflows[r.kind]||workflows.plan,own=r.memberId===currentId;return '<section class="record-entry"><div class="entry-heading"><h3>'+esc(w.title)+'</h3>'+(r.visibility==='private'?'<span class="badge">나와 교사만</span>':'')+'</div><div class="entry-content">'+(recordImages(r).length?'<div class="entry-photos">'+recordImages(r).map((src,i)=>'<button class="entry-photo" data-image="'+esc(r.id)+'" data-photo-index="'+i+'" aria-label="사진 '+(i+1)+' 크게 보기"><img src="'+esc(src)+'" alt="인증 사진 '+(i+1)+'" loading="lazy"><span>사진 '+(i+1)+' 확대</span></button>').join('')+'</div>':'')+'<div class="entry-detail">'+(r.kind==='monthly'?'<p class="hint">'+esc(r.date.slice(0,7))+' 월간 계획</p>':'')+(r.memo?'<p class="entry-memo">'+esc(r.memo)+'</p>':'')+'<div class="social-row"><button data-thread="'+esc(r.id)+'">댓글 '+(r.comments||[]).length+((r.comments||[]).some(c=>data.members.find(m=>m.id===c.memberId)?.role==='teacher')?'   교사 피드백':'')+'</button><button data-thread="'+esc(r.id)+'">응원 '+Object.values(r.reactions||{}).reduce((n,a)=>n+a.length,0)+'</button></div>'+(own?'<div class="entry-actions"><button class="plain" data-edit="'+esc(r.id)+'">수정'+'</button><button class="plain" data-delete="'+esc(r.id)+'">삭제</button></div>':'')+'</div></div></section>'}
function dailyRecordCard(group){const author=data.members.find(m=>m.id===group.memberId),target=group.records.find(r=>r.kind==='target'),actual=group.records.find(r=>r.kind==='study'),order=['plan','monthly','target','plan-night','monthly-night','study'];return '<article class="card daily-record"><header class="day-card-head"><span class="avatar">'+esc(author?.name[0]||'?')+'</span><div><b>'+esc(author?accountLabel(author):'멤버')+'</b><p>'+esc(group.date)+'   하루 기록</p></div><span class="badge">'+group.records.length+'개 인증</span></header>'+((target||actual)?'<div class="day-time-summary"><span>목표 <strong>'+(target?duration(target.minutes):'미등록')+'</strong></span><span>실제 <strong>'+(actual?duration(actual.minutes):'미등록')+'</strong></span>'+(target?.minutes>0&&actual?'<span class="achievement">달성률 '+Math.round(actual.minutes/target.minutes*100)+'%</span>':'')+'</div>':'')+'<div class="day-record-entries">'+[...group.records].sort((a,b)=>order.indexOf(a.kind)-order.indexOf(b.kind)).map(recordSection).join('')+'</div></article>'}
function renderDailyRecords(rows){return groupedRecords(rows).map(dailyRecordCard).join('')}

function render(){syncParticipationTabs();syncYearControls();renderCore();renderSchoolYear();$('participationButton').hidden=!me()||isTeacher();renderPlannerControls();document.querySelector('.period-row').hidden=view==='plan';if(!$('monthFilter').value)$('monthFilter').value=today().slice(0,7);const rows=data.records.filter(r=>canView(r)&&inSchoolYear(r.date)&&(view==='plan'?((isTeacher()||r.memberId===currentId)&&plannerMatches(r)):(isTeacher()&&view==='mine'&&r.kind==='monthly'?r.date.slice(0,7)===$('weekFilter').value.slice(0,7):r.date===$('weekFilter').value))&&(view==='mine'?(isTeacher()||r.memberId===currentId):view==='study'?['target','study'].includes(r.kind):true)).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt.localeCompare(a.updatedAt));$('feed').innerHTML=rows.length?renderDailyRecords(rows):'<div class="empty"><h3>이 날짜에는 인증 기록이 없어요</h3><p>이전 날이나 다른 날짜를 선택해보세요.</p></div>';$('daySummary').textContent=$('weekFilter').value+'   '+groupedRecords(rows).length+'명   '+rows.length+'개 인증'+(view==='plan'&&plannerMode==='monthly'?' (해당 월 계획 사진 포함)':'');if(me()&&!isTeacher()){$('dailyActions').innerHTML=Object.entries(workflows).filter(([k])=>!['monthly','monthly-night'].includes(k)&&allowed(k)).map(([k,w])=>{const r=lookup(currentId,k,today());return `<button data-action="${k}"><span class="phase">${k==='plan'||k==='target'?'MORNING':'EVENING'}</span>${w.title.replace(/^(아침|밤)\s* \s*/, '')}<small>${r?'✓ 등록 완료'+(w.time?'   '+duration(r.minutes):''):'아직 등록하지 않았어요'}</small></button>`}).join('');$('participationButton').textContent=participationNames[me().participation||'both']+'   내 설정';document.querySelectorAll('.intro > button,.mobile-action button').forEach(b=>{b.dataset.action=allowed('plan')?'plan':'target';b.textContent='＋ 오늘 체크인'})}if(me()?.participation==='planner'&&!isTeacher()){$('myTotal').textContent=data.records.filter(r=>r.memberId===currentId&&r.kind==='plan-night'&&inside(r.date)).length+'일';$('myDays').textContent='밤 달성 체크를 남긴 날';document.querySelector('.main-metric p').textContent='나의 플래너 체크'}renderAdminWorkflow();if(view==='ranking')renderRanking()}
$('monthFilter').onchange=render;$('weekFilter').onchange=()=>{const value=$('weekFilter').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!inSchoolYear(value))$('weekFilter').value=schoolDate();render()};$('previousDay').onclick=()=>moveRecordDay(-1);$('nextDay').onclick=()=>moveRecordDay(1);$('todayRecords').onclick=()=>{$('weekFilter').value=today();render()};$('monthlyAdd').onclick=()=>openPlannerRecord(false);$('plannerNightAdd').onclick=()=>openPlannerRecord(true);document.addEventListener('click',e=>{const b=e.target.closest('[data-planner]');if(b){plannerMode=b.dataset.planner;render()}});
function openParticipation(id=currentId){if(id!==currentId&&!isTeacher())return;const member=data.members.find(m=>m.id===id&&m.role==='student');if(!member)return;participationMemberId=id;$('participationName').textContent=accountLabel(member);$('usePlanner').checked=(member.participation||'both')!=='time';$('useTime').checked=(member.participation||'both')!=='planner';$('participationError').textContent='';$('participationDialog').showModal()}
$('participationButton').onclick=()=>openParticipation();$('participationForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{if(participationMemberId!==currentId&&!isTeacher())throw Error('변경 권한이 없어요.');const next=structuredClone(data),m=next.members.find(m=>m.id===participationMemberId);if(!m||m.role!=='student')throw Error('학생을 찾을 수 없어요.');if(!$('usePlanner').checked&&!$('useTime').checked)throw Error('플래너 또는 시간체크 중 하나 이상을 선택해주세요.');m.participation=$('usePlanner').checked?($('useTime').checked?'both':'planner'):'time';await commit(next);render();$('participationDialog').close();notify('참여 방식을 변경했어요. 이전 기록은 유지됩니다.')}catch(err){$('participationError').textContent=storageError(err)}finally{e.submitter.disabled=false}};
function renderAdminWorkflow(){if(!isTeacher())return;const date=$('teacherDate').value||schoolDate(),query=$('adminSearch').value.trim().toLowerCase();$('teacherDate').value=date;const members=data.members.filter(m=>m.role==='student'&&`${m.name} ${m.username} ${m.className}`.toLowerCase().includes(query));$('adminList').innerHTML=members.map(m=>`<article class="admin-card"><div class="row"><h3>${esc(accountLabel(m))}</h3><button class="soft" data-reset="${m.id}">${m.auth?'비밀번호 초기화':'계정 활성화'}</button></div><p>아이디 <b>${esc(m.username)}</b>   ${participationNames[m.participation||'both']}</p><div class="status-tags">${Object.entries(workflows).filter(([k])=>allowed(k,m)).map(([k,w])=>`<span class="${lookup(m.id,k,k==='monthly'?date.slice(0,7)+'-01':date)?'done':''}">${w.title} ${lookup(m.id,k,k==='monthly'?date.slice(0,7)+'-01':date)?'완료':'미등록'}</span>`).join('')}</div><div class="social-row"><button data-participation="${m.id}">참여 방식 변경</button><button class="danger" data-delete-student="${m.id}">학생 삭제</button><button data-student-records="${m.id}">기록 피드백 보기</button></div></article>`).join('')||'<p class="sub">조건에 맞는 학생이 없어요.</p>'}
$('teacherDate').onchange=renderAdminWorkflow;$('adminSearch').oninput=renderAdminWorkflow;
function threadRecord(){const r=data.records.find(r=>r.id===threadId);return r&&canView(r)?r:null}
function renderThread(){const r=threadRecord();if(!r){$('threadDialog').close();$('threadList').innerHTML='';return}$('threadTitle').textContent=`${data.members.find(m=>m.id===r.memberId)?.name||'학생'}   ${workflows[r.kind].title}   ${r.date}`;$('threadReactions').innerHTML=['👏','💪','❤️'].map(emoji=>`<button class="soft" data-react="${emoji}" aria-label="${emoji} 반응" aria-pressed="${(r.reactions?.[emoji]||[]).includes(currentId)}">${emoji} ${(r.reactions?.[emoji]||[]).length}</button>`).join('');$('threadList').innerHTML=(r.comments||[]).map(c=>{const m=data.members.find(m=>m.id===c.memberId);return `<div class="comment"><b>${esc(m?accountLabel(m):'멤버')}</b> ${m?.role==='teacher'?'<span class="badge role-label">교사 피드백</span>':''}<p>${esc(c.text)}</p><small>${new Date(c.createdAt).toLocaleString('ko-KR')}</small>${c.memberId===currentId?`<button class="plain" data-remove-comment="${c.id}">삭제</button>`:''}</div>`}).join('')||'<p class="sub">첫 응원이나 피드백을 남겨주세요.</p>'}
async function addComment(text){const r=threadRecord();if(!r)throw Error('이 기록을 볼 수 없어요.');text=text.trim();if(!text||text.length>500)throw Error('댓글은 1~500자로 입력해주세요.');const next=structuredClone(data),record=next.records.find(x=>x.id===r.id);record.comments??=[];record.comments.push({id:uid(),memberId:currentId,text,createdAt:new Date().toISOString()});await commit(next)}
$('commentForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await addComment($('commentText').value);$('commentText').value='';$('threadError').textContent='';render();renderThread()}catch(err){$('threadError').textContent=storageError(err)}finally{e.submitter.disabled=false}};
async function toggleReaction(emoji){if(!['👏','💪','❤️'].includes(emoji))return;const r=threadRecord();if(!r)throw Error('이 기록을 볼 수 없어요.');const next=structuredClone(data),record=next.records.find(x=>x.id===r.id);record.reactions??={};const list=record.reactions[emoji]||[];record.reactions[emoji]=list.includes(currentId)?list.filter(id=>id!==currentId):[...list,currentId];await commit(next)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-thread]');if(b){threadId=b.dataset.thread;if(!threadRecord())return;$('threadError').textContent='';$('commentText').value='';renderThread();$('threadDialog').showModal()}const mode=e.target.closest('[data-participation]');if(mode)openParticipation(mode.dataset.participation);const student=e.target.closest('[data-student-records]');if(student&&isTeacher()){view='mine';render();$('feedTitle').textContent='학생 기록   피드백';$('feedSubtitle').textContent='선택 기간의 일일 기록과 선택 월의 월간 플래너';$('feed').innerHTML=renderDailyRecords(data.records.filter(r=>r.memberId===student.dataset.studentRecords&&canView(r)&&inSchoolYear(r.date)&&(r.kind==='monthly'?r.date.slice(0,7)===$('monthFilter').value:inside(r.date))))||'<p class="sub">해당 기간의 기록이 없어요.</p>';$('feed').scrollIntoView({behavior:'smooth',block:'start'})}const reaction=e.target.closest('[data-react]');if(reaction){reaction.disabled=true;try{await toggleReaction(reaction.dataset.react);render();renderThread()}catch(err){$('threadError').textContent=storageError(err)}finally{reaction.disabled=false}}const remove=e.target.closest('[data-remove-comment]');if(remove){try{const r=threadRecord();if(!r)throw Error('접근할 수 없어요.');const next=structuredClone(data),record=next.records.find(x=>x.id===r.id);record.comments=(record.comments||[]).filter(c=>!(c.id===remove.dataset.removeComment&&c.memberId===currentId));await commit(next);render();renderThread()}catch(err){$('threadError').textContent=storageError(err)}}});
function schoolYearValue(){const now=new Date();return Number.isInteger(data.schoolYear)&&data.schoolYear>=1900&&data.schoolYear<=9998?data.schoolYear:now.getFullYear()-(now.getMonth()<2?1:0)}
function renderSchoolYear(){const year=schoolYearValue();$('schoolYearBadge').textContent=year+'학년도';$('schoolYearCurrent').textContent=`현재 ${year}학년도   ${year}.03.01 ~ ${year+1}.02.${new Date(year+1,2,0).getDate()}`;if(document.activeElement!==$('schoolYearInput'))$('schoolYearInput').value=year}
$('schoolYearForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;$('schoolYearError').textContent='';$('schoolYearSaved').textContent='';button.disabled=true;try{requireTeacher();const year=Number($('schoolYearInput').value);if(!Number.isInteger(year)||year<1900||year>9998)throw Error('학년도를 1900~9998 사이의 연도로 입력해주세요.');const next=structuredClone(data);next.schoolYear=year;await commit(next);periodId='school-year';render();$('schoolYearSaved').textContent=year+'학년도로 저장했어요.';notify(year+'학년도로 설정했어요.')}catch(err){$('schoolYearError').textContent=storageError(err)}finally{button.disabled=false}};

function schoolYearBounds(){const y=schoolYearValue();return {start:y+'-03-01',end:(y+1)+'-02-'+new Date(y+1,2,0).getDate()}}
function inSchoolYear(date){const b=schoolYearBounds();return date>=b.start&&date<=b.end}
function yearPeriods(){const b=schoolYearBounds();return [{id:'school-year',...b},...data.periods.filter(p=>p.start<=b.end&&p.end>=b.start).map(p=>({...p,start:p.start<b.start?b.start:p.start,end:p.end>b.end?b.end:p.end}))]}
function schoolDate(){return inSchoolYear(today())?today():schoolYearBounds().start}
function syncYearControls(){const b=schoolYearBounds();if(!yearPeriods().some(p=>p.id===periodId))periodId='school-year';for(const id of ['teacherDate','monthFilter','weekFilter']){const el=$(id),month=id==='monthFilter';el.min=month?b.start.slice(0,7):b.start;el.max=month?b.end.slice(0,7):b.end;if(!el.value||el.value<el.min||el.value>el.max)el.value=month?schoolDate().slice(0,7):schoolDate()}}
function showStorageNotice(message){$('storageNotice').hidden=false;$('storageNoticeText').textContent=message}
$('reloadStorage').onclick=()=>{if(confirm('저장하지 않은 입력은 사라집니다. 최신 데이터를 다시 불러올까요?'))location.reload()};


function moveRecordDay(offset){const d=new Date($('weekFilter').value+'T12:00:00');d.setDate(d.getDate()+offset);const value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');if(inSchoolYear(value)){$('weekFilter').value=value;render()}}
function plannerMatches(r){const date=$('weekFilter').value;if(plannerMode==='monthly')return r.kind==='monthly'?r.date.slice(0,7)===date.slice(0,7):r.kind==='monthly-night'&&r.date===date;return ['plan','plan-night'].includes(r.kind)&&r.date===date}
function renderPlannerControls(){const visible=view==='plan',date=$('weekFilter').value,b=schoolYearBounds();$('dailyBrowser').hidden=!['home','plan','study','mine'].includes(view);$('previousDay').disabled=date<=b.start;$('nextDay').disabled=date>=b.end;$('todayRecords').disabled=!inSchoolYear(today());$('plannerTabs').hidden=!visible;$('monthFilter').hidden=true;$('monthFilter').value=date.slice(0,7);$('monthlyAdd').hidden=!visible||!allowed(plannerMode==='monthly'?'monthly':'plan');$('plannerNightAdd').hidden=$('monthlyAdd').hidden;if(view==='study'){$('monthlyAdd').hidden=!allowed('target');$('plannerNightAdd').hidden=!allowed('study')}$('monthlyAdd').textContent=view==='study'?'아침 목표 시간 입력':'아침 계획 사진';$('plannerNightAdd').textContent=view==='study'?'밤 실제 시간 사진 인증':'밤 달성 체크 사진';document.querySelectorAll('[data-planner]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.planner===plannerMode));if(visible){$('feedTitle').textContent=plannerMode==='monthly'?'월간 플래너':'일일 플래너';$('feedSubtitle').textContent=plannerMode==='monthly'?'해당 월 계획 사진과 선택한 날짜의 밤 달성 체크를 확인해요.':'선택한 날짜의 아침 계획 사진과 밤 달성 체크를 확인해요.'}else if(['home','study','mine'].includes(view))$('feedSubtitle').textContent='날짜를 선택해 하루의 인증을 확인해요. 상단 통계는 누적 기간 기준입니다.';}
