function syncParticipationTabs(){const teacher=isTeacher();document.querySelectorAll('[data-view="home"]').forEach(b=>b.hidden=teacher);if(teacher&&['home','plan','study'].includes(view))view='mine';const planner=!teacher&&allowed('plan'),time=!teacher&&allowed('target');document.querySelectorAll('[data-view="plan"]').forEach(b=>b.hidden=!planner);document.querySelectorAll('[data-view="study"]').forEach(b=>b.hidden=!time);if((view==='plan'&&!planner)||(view==='study'&&!time))view='home'}


let rankingScope='week';
function dateShift(date,days){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function rankingBounds(){const chosen=data.rankingWeekStart||schoolDate();const d=new Date(chosen+'T12:00:00Z');const start=data.rankingWeekStart||dateShift(chosen,-((d.getUTCDay()+6)%7));return {start,end:dateShift(start,6)}}
function rankingRows(scope){const b=rankingBounds();return data.members.filter(m=>m.role==='student'&&(m.participation||'both')!=='planner').map(m=>({m,total:(data.studyTotals||data.records).filter(r=>r.memberId===m.id&&r.kind==='study'&&(scope==='all'?inSchoolYear(r.date):r.date>=b.start&&r.date<=b.end)).reduce((n,r)=>n+(Number(r.minutes)||0),0)})).sort((a,b)=>b.total-a.total||a.m.name.localeCompare(b.m.name,'ko'))}
function renderRanking(){const b=rankingBounds(),rows=rankingRows(rankingScope);$('feedTitle').textContent='공부시간 순위';$('feedSubtitle').textContent=rankingScope==='week'?b.start+' ~ '+b.end+' (교사 설정)':schoolYearValue()+'학년도 누적 ('+schoolYearBounds().start+' ~ '+schoolYearBounds().end+')';$('dailyBrowser').hidden=true;$('feed').hidden=false;$('feed').innerHTML='<section class="panel ranking-panel"><div class="kind-switch"><button data-rank="week" aria-pressed="'+(rankingScope==='week')+'">주간 순위</button><button data-rank="all" aria-pressed="'+(rankingScope==='all')+'">전체 시간 순위</button></div><p class="hint">플래너만 참여하는 학생과 목표 시간은 집계하지 않습니다. 같은 시간은 공동 순위입니다.</p>'+ (rows.length?rows.map((x,i)=>'<div class="member-row"><b class="rank-number">'+(rows.findIndex(y=>y.total===x.total)+1)+'</b><div class="member-info">'+esc(accountLabel(x.m))+'</div><strong>'+duration(x.total)+'</strong></div>').join(''):'<p class="empty">시간체크에 참여하는 학생이 없습니다.</p>')+'</section>'}
function updateTimePreview(){const el=$('timePreview');if(el){el.textContent=(kind==='target'?'오늘 목표 ':'실제 공부 ')+duration((Number($('hours').value)||0)*60+(Number($('minutes').value)||0))}}
