 const panel=document.createElement('section');panel.className='admin-card';panel.innerHTML='<h3>주간 공부시간 순위 설정</h3><form id="rankingWeekForm"><label for="rankingWeekStart">집계 시작일</label><input type="date" id="rankingWeekStart" required><p class="hint">시작일부터 7일간의 실제 공부시간을 집계합니다. 모든 학생의 주간 순위에 적용됩니다.</p><p id="rankingWeekRange" class="hint"></p><button type="submit">주간 설정 저장</button><p id="rankingWeekMessage" role="status"></p></form>';$('adminArea').prepend(panel);
