 $('rankingWeekForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{requireTeacher();const start=$('rankingWeekStart').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(start))throw Error('시작일을 선택해주세요.');const next=structuredClone(data);next.rankingWeekStart=start;await commit(next);$('rankingWeekMessage').textContent='주간 순위 기간을 저장했어요.'}catch(err){$('rankingWeekMessage').textContent=storageError(err)}finally{button.disabled=false}};
