// Authenticated server integration. No account hashes or records are kept in browser storage.
let serverSetup=false,requestsPending=0;
async function api(path,payload,method=payload===undefined?'GET':'POST') {
  requestsPending++;
  try {
    const res=await fetch(path,{method,credentials:'same-origin',headers:payload===undefined?{}:{'Content-Type':'application/json'},body:payload===undefined?undefined:JSON.stringify(payload),signal:AbortSignal.timeout(45000)});
    const result=await res.json();
    if(!res.ok)throw Object.assign(Error(result.error||'요청을 처리하지 못했습니다.'),{status:res.status,name:res.status===409?'ConflictError':'Error'});
    return result;
  } catch(e) {if(e.name==='TimeoutError'||e instanceof TypeError)throw Error('서버 연결을 확인해주세요. 저장 여부가 불확실하면 최신 데이터를 다시 불러온 후 확인해주세요.');throw e;}
  finally {requestsPending--;}
}
async function commit(next) {
  if(!storageReady)throw Error('최신 데이터를 다시 불러온 뒤 저장해주세요.');
  try {data=await api('/api/state',next,'PUT');}
  catch(e){if(e.status===409){storageReady=false;showStorageNotice(e.message)}throw e;}
}
function acceptSession(result) {
  serverSetup=false;
  $('welcomeDialog').close();
  if(result.member.mustReset){currentId=null;pendingLoginId=result.member.id;$('passwordForm').reset();$('passwordError').textContent='';$('passwordDialog').showModal();return;}
  data=result.data;storageReady=true;$('storageNotice').hidden=true;finishLogin(result.member);
}
$('welcomeForm').onsubmit=async e=>{
  e.preventDefault();$('enterButton').disabled=true;$('welcomeError').textContent='';
  try {
    const password=$('loginPassword').value;
    if(authMode!=='login')passwordValid(password,$('confirmPassword').value);
    const result=await api(authMode==='login'?'/api/login':'/api/register',{username:$('loginId').value.trim().toLowerCase(),password,name:normalize($('welcomeName').value),className:normalize($('className').value),participation:$('joinMode').value,code:$('inviteCode').value});
    acceptSession(result);$('welcomeForm').reset();
  }catch(err){$('welcomeError').textContent=storageError(err)}finally{$('enterButton').disabled=false;}
};
$('switchUser').onclick=async()=>{
  try {
    await api('/api/logout',{});currentId=null;threadId=null;pendingLoginId=null;
    data=initialData();view='home';$('fullImage').removeAttribute('src');$('threadList').innerHTML='';$('adminSearch').value='';render();showWelcome();
  }catch(e){notify(e.message)}
};
$('passwordForm').onsubmit=async e=>{
  e.preventDefault();e.submitter.disabled=true;
  try {passwordValid($('newPassword').value,$('newPasswordConfirm').value);const result=await api('/api/password',{password:$('newPassword').value});$('passwordDialog').close();$('passwordForm').reset();acceptSession(result);}
  catch(e){$('passwordError').textContent=e.message}finally{e.submitter.disabled=false;}
};
async function resetStudent(id,password){const result=await api('/api/reset-student',{id,password});data=result.data;return result;}
async function deleteStudentAccount(id,password){const result=await api('/api/delete-student',{id,password});data=result.data;return result.name;}
async function downloadBackup(suffix='backup') {
  requireTeacher();const payload=await api('/api/backup'),blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download='study-board-'+suffix+'-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
let pendingBackup=null;
function setupBackup(){
  const panel=document.createElement('section');panel.className='admin-card';panel.style.marginBottom='20px';
  panel.innerHTML='<h3>서버 백업 및 복원</h3><p class="hint">기록·설정·계정과 사진 경로를 백업합니다. 사진 원본은 같은 Supabase Storage에 보관됩니다. 다른 프로젝트로 이전하려면 Storage도 별도 백업해주세요. 복원 시 전체 데이터가 교체되고 모두 로그아웃됩니다.</p><div class="form-actions"><button type="button" id="exportBackup">서버 백업 다운로드</button><button type="button" class="soft" id="chooseBackup">백업 불러오기</button></div><input type="file" id="backupFile" accept=".json,application/json" hidden><div id="backupReview" hidden><p id="backupSummary"></p><label for="restorePassword">교사 비밀번호 확인</label><input id="restorePassword" type="password" autocomplete="current-password"><div class="form-actions"><button type="button" class="danger" id="restoreBackup">백업 후 전체 데이터 교체</button><button type="button" class="soft" id="cancelBackup">취소</button></div></div><p id="backupMessage" role="status"></p>';
  $('adminArea').prepend(panel);
  $('exportBackup').onclick=async()=>{const b=$('exportBackup');b.disabled=true;try{await downloadBackup();$('backupMessage').textContent='백업 다운로드를 시작했습니다.'}catch(e){$('backupMessage').textContent=e.message}finally{b.disabled=false;}};
  $('chooseBackup').onclick=()=>$('backupFile').click();
  $('backupFile').onchange=async e=>{pendingBackup=null;$('backupReview').hidden=true;try{const f=e.target.files[0];if(!f)return;if(f.size>46*1024*1024)throw Error('백업 파일이 너무 큽니다.');const p=JSON.parse(await f.text());if(!['study-board-server-backup','study-board-backup'].includes(p.format)||p.version!==1||!Array.isArray(p.data?.members)||!Array.isArray(p.data?.records))throw Error('지원하는 스터디 보드 백업이 아닙니다.');pendingBackup=p;$('backupSummary').textContent='계정 '+p.data.members.length+'명 / 기록 '+p.data.records.length+'개 — 전체 교체';$('backupReview').hidden=false;$('backupMessage').textContent='복원 전 서버가 데이터 형식과 권한을 다시 확인합니다.';}catch(err){$('backupMessage').textContent=err.message}finally{e.target.value='';}};
  $('cancelBackup').onclick=()=>{pendingBackup=null;$('backupReview').hidden=true;$('restorePassword').value='';};
  $('restoreBackup').onclick=async()=>{const b=$('restoreBackup');b.disabled=true;try{if(!pendingBackup)throw Error('백업을 먼저 선택해주세요.');if(!$('restorePassword').value)throw Error('교사 비밀번호를 입력해주세요.');await downloadBackup('before-restore');await api('/api/restore',{password:$('restorePassword').value,backup:pendingBackup});location.reload();}catch(e){$('backupMessage').textContent=e.message}finally{$('restorePassword').value='';b.disabled=false;}};
}
async function init() {
  setupEnhancements();setupBackup();setupPolish();setupStudentDeletion();
  try {const result=await api('/api/bootstrap');serverSetup=result.setup;storageReady=true;periodId='school-year';if(result.data)data=result.data;render();if(result.member)acceptSession(result);else showWelcome();}
  catch(e){storageReady=false;render();showStorageNotice('서버에 연결하지 못했습니다. '+e.message);}
}
setInterval(async()=>{
  if(!me()||!storageReady||requestsPending||document.hidden||document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
  const revision=data.revision;
  try {const version=await api('/api/version');if(version.revision!==revision){const fresh=await api('/api/state');if(data.revision===revision&&!requestsPending&&!document.querySelector('dialog[open]')){data=fresh;render();}}}
  catch(e){if(e.status===401){storageReady=false;showStorageNotice('로그인이 만료되었습니다. 새로고침 후 로그인해주세요.');}}
},20000);
init();

